using System;
using System.Collections.ObjectModel;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Input;
using RagnarokCompanion.Services;
namespace RagnarokCompanion.ViewModels;
public sealed partial class BuildViewModel
{
 bool isAdmin;public bool IsAdmin {get=>isAdmin;private set{isAdmin=value;Changed();if(!value&&Area==3)Area=1;}}
 public bool IsModeration=>Area==3&&IsAdmin;
 public ObservableCollection<BuildSubmission> PendingBuilds {get;}=new();
 BuildSubmission? selectedSubmission;public BuildSubmission? SelectedSubmission {get=>selectedSubmission;set{selectedSubmission=value;SetReviewPreview();ReviewConfirmed=false;ModerationReason="";AdminNotes="";Changed();Changed(nameof(ReviewText));Changed(nameof(IsReviewOpen));}}
 public bool IsReviewOpen=>SelectedSubmission!=null&&IsAdmin;public ICommand OpenReviewCommand=>new RelayCommand(async value=>{if(Busy||!IsAdmin||value is not BuildSubmission row)return;Busy=true;try{if(communitySync!=null)row=await communitySync.SubmissionContent(row,cancellation.Token);SelectedSubmission=row;}catch(Exception e){Tell(e.Message);}finally{Busy=false;}});public ICommand CloseReviewCommand=>new RelayCommand(_=>{if(!Busy)SelectedSubmission=null;});
 bool reviewConfirmed;public bool ReviewConfirmed {get=>reviewConfirmed;set{reviewConfirmed=value;Changed();}}
 string moderationReason="";public string ModerationReason {get=>moderationReason;set{moderationReason=value??"";Changed();}}
 string adminNotes="";public string AdminNotes {get=>adminNotes;set{adminNotes=value??"";Changed();}}
 public string ReviewText {get{var row=SelectedSubmission;if(row==null)return "Selecione uma submissão para revisar.";var b=row.Build;if(row.Issue.Length>0)return row.Issue+" Rejeite com orientações para o autor.";try{var errors=validator.Validate(b,Criteria);return b.Title+"\nAutor: "+BuildPublicName.Clean(row.Fields.TryGetValue("authorName",out var author)?author.GetProperty("stringValue").GetString():null)+"\n"+(Classes.FirstOrDefault(c=>c.Id==b.ClassId)?.Name??b.ClassId)+" · "+b.Stage+" · "+b.Purpose+"\n\nAtributos: "+string.Join(" · ",b.Stats.Select(p=>p.Key+" "+p.Value))+"\n\n"+string.Join("\n\n",b.Equipment.Where(e=>e.ItemId!=null).Select(e=>(BuildCatalog.Slots.FirstOrDefault(s=>s.Id==e.Slot)?.Name??e.Slot)+": +"+e.Refine+" "+(FindItem(e.ItemId!.Value)?.Name??"#"+e.ItemId)+" ["+e.Grade+"]\nCartas: "+string.Join(", ",e.Cards.Select(id=>FindItem(id)?.Name??"#"+id))+"\nEncantamentos: "+string.Join(", ",e.Enchants.Select(id=>FindItem(id)?.Name??"#"+id))+"\nRandom Options: "+string.Join("; ",e.RandomOptions)))+"\n\nNotas: "+b.Notes+"\n\nValidação local: "+(errors.Count==0?"sem pendências. Confira os critérios oficiais antes de aprovar.":string.Join("\n",errors));}catch{return "Dados inválidos nesta submissão. Rejeite com um motivo ou confira no Console.";}}}
 public ICommand CheckAdminCommand=>new RelayCommand(async _=>await RefreshAdmin());
 public ICommand FetchPendingCommand=>new RelayCommand(async _=>await FetchPending());
 public ICommand ApproveBuildCommand=>new RelayCommand(async _=>await ModerateSelected(true));
 public ICommand RejectBuildCommand=>new RelayCommand(async _=>await ModerateSelected(false));
 async Task RefreshAdmin(){if(Busy||community is not FirestoreBuildGateway f)return;Busy=true;try{IsAdmin=await f.CheckAdmin(cancellation.Token);if(!IsAdmin){PendingBuilds.Clear();SelectedSubmission=null;}Tell(IsAdmin?"Conta administrativa confirmada pelo Firebase.":"Conta sem permissão administrativa. O UID deve ser cadastrado em admins pelo responsável do projeto.");}catch{IsAdmin=false;Tell("Não foi possível verificar a permissão administrativa.");}finally{Busy=false;}}
 string? pendingCursor;public bool HasMorePending {get;private set;}public ICommand MorePendingCommand=>new RelayCommand(async _=>await MorePending());
 async Task MorePending(){if(!FirebaseOnline)return;if(Busy||!IsAdmin||!HasMorePending||community is not FirestoreBuildGateway f)return;Busy=true;try{var rows=await f.Pending(cancellation.Token,pendingCursor);foreach(var row in rows)PendingBuilds.Add(row);pendingCursor=rows.Count>0?rows[^1].Path:pendingCursor;HasMorePending=rows.Count==20;Changed(nameof(HasMorePending));}catch(Exception e){Tell(e.Message);}finally{Busy=false;}}
 DateTimeOffset pendingFetched;
 async Task FetchPending(){if(!FirebaseOnline){Tell("Sem conexão. Pedidos já carregados continuam disponíveis.");return;}if(Busy||!IsAdmin||community is not FirestoreBuildGateway f)return;if(DateTimeOffset.UtcNow-pendingFetched<TimeSpan.FromSeconds(30)){Tell("Aguarde 30 segundos para atualizar a fila.");return;}Busy=true;try{var rows=await f.Pending(cancellation.Token);PendingBuilds.Clear();SelectedSubmission=null;foreach(var row in rows)PendingBuilds.Add(row);pendingCursor=rows.Count>0?rows[^1].Path:null;HasMorePending=rows.Count==20;Changed(nameof(HasMorePending));pendingFetched=DateTimeOffset.UtcNow;Tell(rows.Count+" submissões pendentes carregadas (até 20 por consulta).");}catch(Exception e){Tell(e.Message);}finally{Busy=false;}}
 async Task ModerateSelected(bool approve){if(!FirebaseOnline){Tell("Aprovação exige conexão com o Firebase.");return;}if(Busy||!IsAdmin||SelectedSubmission is not {} row||community is not FirestoreBuildGateway f)return;if(approve&&row.Issue.Length>0){Tell(row.Issue);return;}if(approve&&!ReviewConfirmed){Tell("Confirme que revisou os equipamentos e os critérios oficiais.");return;}if(approve){try{if(validator.Validate(row.Build,Criteria).Count>0){Tell("Há pendências na build. Rejeite com orientações para o autor corrigir.");return;}}catch{Tell("Dados inválidos. Não é possível aprovar.");return;}}Busy=true;try{await f.Moderate(row,approve,ModerationReason,cancellation.Token,AdminNotes);PendingBuilds.Remove(row);SelectedSubmission=null;Tell(approve?"Build aprovada. Snapshot e combinação registrados juntos no Firebase. Sincronize a comunidade para atualizar o progresso.":"Build rejeitada. O rascunho do autor foi preservado.");}catch(Exception e){Tell("Ação não concluída. Se o autor editou a build, atualize a fila antes de revisar novamente. "+e.Message);}finally{Busy=false;}}
}
